import json, random, sys, itertools
sys.path.insert(0,'/app')
from main import solve

def ref_solve(req):
    # brute force: enumerate all traces recursively, no state dedup
    mem0=tuple(req['memory'])
    progs=[list(t) for t in req['threads']]
    n=len(progs)
    outcomes=set()
    def rec(mem, pcs, bufs, obss):
        enabled=[]
        for i in range(n):
            if pcs[i]<len(progs[i]):
                ins=progs[i][pcs[i]]
                op=ins[0]
                if op=='fence' or op=='xchg':
                    if not bufs[i]: enabled.append(('exec',i))
                else:
                    enabled.append(('exec',i))
            if bufs[i]: enabled.append(('drain',i))
        if not enabled:
            assert all(pcs[i]==len(progs[i]) for i in range(n)) and all(not b for b in bufs)
            outcomes.add((tuple(obss),mem)); return
        for kind,i in enabled:
            mem2=list(mem); pcs2=list(pcs)
            bufs2=[list(b) for b in bufs]; obs2=[list(o) for o in obss]
            if kind=='drain':
                a,w,v=bufs2[i].pop(0)
                for k in range(w): mem2[a+k]=(v>>(8*k))&255
            else:
                ins=progs[i][pcs2[i]]; pcs2[i]+=1; op=ins[0]
                if op=='store': bufs2[i].append((ins[1],ins[2],ins[3]))
                elif op=='load':
                    a,w=ins[1],ins[2]; val=0
                    for k in range(w):
                        ad=a+k; b=None
                        for (sa,sw,sv) in reversed(bufs2[i]):
                            if sa<=ad<sa+sw: b=(sv>>(8*(ad-sa)))&255; break
                        if b is None: b=mem2[ad]
                        val|=b<<(8*k)
                    obs2[i].append(val)
                elif op=='xchg':
                    a,w,v=ins[1],ins[2],ins[3]; old=0
                    for k in range(w):
                        old|=mem2[a+k]<<(8*k); mem2[a+k]=(v>>(8*k))&255
                    obs2[i].append(old)
                # fence: nothing
            rec(tuple(mem2),tuple(pcs2),tuple(tuple(b) for b in bufs2),tuple(tuple(o) for o in obs2))
    rec(mem0,(0,)*n,tuple(() for _ in range(n)),tuple(() for _ in range(n)))
    return {'outcomes':[{'reads':[list(o) for o in obss],'memory':list(m)} for obss,m in outcomes]}

def key(o): return json.dumps({'reads':o['reads'],'memory':o['memory']},sort_keys=True)

def gen(rng):
    nmem=rng.randint(1,8)
    mem=[rng.randint(0,255) for _ in range(nmem)]
    nt=rng.randint(1,3)
    threads=[]; total=0
    for _ in range(nt):
        k=rng.randint(0,4)
        if total+k>10: k=10-total
        prog=[]
        for _ in range(k):
            op=rng.choice(['store','load','fence','xchg','store','load'])
            if op=='fence': prog.append(['fence'])
            else:
                w=rng.choice([1,2,4])
                if w>nmem: w=1
                a=rng.randint(0,nmem-w)
                if op=='load': prog.append(['load',a,w])
                elif op=='store': prog.append(['store',a,w,rng.randint(0,(1<<(8*w))-1)])
                else: prog.append(['xchg',a,w,rng.randint(0,(1<<(8*w))-1)])
        threads.append(prog); total+=k
    return {'memory':mem,'threads':threads}

rng=random.Random(12345)
bad=0
for t in range(4000):
    req=gen(rng)
    # keep trace counts manageable: skip if too many instrs for brute force
    tot=sum(len(p) for p in req['threads'])
    if tot>7: continue
    a={key(o) for o in solve(req)['outcomes']}
    b={key(o) for o in ref_solve(req)['outcomes']}
    if a!=b:
        bad+=1
        print('MISMATCH', json.dumps(req))
        print('main only:', sorted(a-b)[:3])
        print('ref only:', sorted(b-a)[:3])
        if bad>3: break
print('done, mismatches:', bad)
